function checkForIrregularConjugation(entry) {
  if (entry.p === "\u062A\u0644\u0644" && entry.f === "tlul") {
    return tlul;
  }
  if (entry.p === "\u0648\u0631\u06A9\u0648\u0644" && entry.f.includes("w\u0103rkawul")) {
    return warkawul;
  }
  if (entry.p === "\u06A9\u0648\u0644" && entry.e.includes("to do")) {
    return kawulDyn;
  }
  if (entry.p === "\u06A9\u0648\u0644" && entry.e.includes("to make")) {
    return kawulStat;
  }
  if (entry.p === "\u06A9\u06D0\u062F\u0644" && entry.e.includes("to become")) {
    return kedulStat;
  }
  if (entry.p === "\u06A9\u06D0\u062F\u0644" && entry.e.includes("to happen")) {
    return kedulDyn;
  }
  if (entry.p === "\u0648\u0631\u06A9\u0648\u0644") {
    return warkawul;
  }
  if (entry.p === "\u062F\u0631\u06A9\u0648\u0644") {
    return darkawul;
  }
  if (entry.p === "\u0631\u0627\u06A9\u0648\u0644") {
    return raakawul;
  }
  return null;
}

